def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append((color, cells))

    # Identify the L-shaped line component that supplies the replacement color.
    marker = None
    for color, cells in components:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        if min(rs) == max(rs) or min(cs) == max(cs):
            continue
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        shape = set(cells)
        for corner_r in (r0, r1):
            for corner_c in (c0, c1):
                expected = ({(corner_r, c) for c in range(c0, c1 + 1)} |
                            {(r, corner_c) for r in range(r0, r1 + 1)})
                if shape == expected:
                    marker = color
                    break
            if marker is not None:
                break
        if marker is not None:
            break

    if marker is None or not components:
        return [row[:] for row in grid]

    targets = [(color, cells) for color, cells in components if color != marker]
    if not targets:
        return [row[:] for row in grid]
    _, target_cells = max(targets, key=lambda item: len(item[1]))

    out = [row[:] for row in grid]
    for r, c in target_cells:
        out[r][c] = marker
    return out
